self.addEventListener("install",()=>self.skipWaiting());self.addEventListener("activate",event=>event.waitUntil(self.clients.claim()));self.addEventListener("push",event=>{let message={title:"Novo pedido no trailer",body:"Abra o painel para conferir a fila."};try{message=event.data.json()}catch{}event.waitUntil(self.registration.showNotification(message.title,{body:message.body,icon:"/assets/favicon.svg",badge:"/assets/favicon.svg",tag:message.tag||"renato-new-order",data:{url:"/painel"}}))});self.addEventListener("notificationclick",event=>{event.notification.close();event.waitUntil(self.clients.matchAll({type:"window",includeUncontrolled:true}).then(async clients=>{const panel=clients.find(client=>new URL(client.url).pathname==="/painel");if(panel)return panel.focus();return self.clients.openWindow("/painel")}))});
